insert into public.knowledge_entries(doc_id,title,category,subcategory,summary,content,keywords,source_title,source_url,metadata,status,review_status,evidence_level)
select doc_id,title,'Penyakit Tanaman','Katalog referensi PM',summary,content,keywords,source_title,source_url,metadata,'published',
  'Ringkasan editorial berdasarkan publikasi pemerintah; belum divalidasi ahli.','Rujukan publik pemerintah; bukan pemeriksaan lapangan'
from jsonb_to_recordset('[{"doc_id":"PM-DISEASE-STEMPHYLIUM-001","title":"Hawar daun Stemphylium","summary":"Bercak pucat pada daun dapat melebar dan menyatu hingga bagian yang rusak berwarna cokelat tua atau kehitaman.","content":"# Hawar daun Stemphylium\n\nBercak pucat pada daun dapat melebar dan menyatu hingga bagian yang rusak berwarna cokelat tua atau kehitaman.\n\nPenyebab: Stemphylium vesicarium.\n\n## Gejala yang diamati\n- Amati bercak awal berwarna kuning muda atau cokelat muda pada daun.\n- Bercak yang meluas dapat menyatu. Bagian yang rusak dapat menggelap dan membusuk.\n- Pada tanaman yang sedang berbunga, tangkai bunga yang terserang dapat mengering dan terkulai.\n\n## Pencegahan\n- Pilih bahan tanam yang sehat dan singkirkan sisa tanaman sakit dari lahan.\n- Pantau daun lebih sering ketika tajuk lama lembap atau banyak embun.\n- Pada pertanaman untuk benih biji, periksa daun dan tangkai bunga sejak awal pembungaan.\n\n## Tindakan awal\n- Catat letak dan perkembangan bercak pada beberapa tanaman.\n- Jika tanaman berbunga, periksa tangkai bunga yang mengering atau terkulai.\n- Tunjukkan foto dan catatan perkembangan gejala kepada POPT atau penyuluh sebelum memilih tindakan pengendalian.\n\n## Jangan tertukar\nHawar Stemphylium dapat muncul bersama bercak ungu. Warna bercak yang menggelap saja belum cukup untuk membedakan keduanya.\n\nReferensi edukasi, bukan diagnosis pasti. Gejala dapat saling menyerupai. Konsultasikan tanaman yang memburuk kepada POPT atau penyuluh; jangan menentukan pestisida hanya dari foto.\n\n## Sumber\n- [Benih Biji Bawang Merah di Indonesia · bagian 6.2.5 dan 6.4](https://repository.pertanian.go.id/server/api/core/bitstreams/4a250672-f833-42cc-83d5-35327f1d5e3e/content) — Rosliani dkk., IAARD Press, Kementerian Pertanian, 2022.\n- [Pengenalan Hama dan Penyakit pada Tanaman Bawang Merah dan Pengendaliannya · bagian 2.2.5](https://repository.pertanian.go.id/server/api/core/bitstreams/2cae6926-4681-4cfc-b1dc-2219b18c474d/content#page=29) — Udiarto, Setiawati & Suryaningsih, Balai Penelitian Tanaman Sayuran, 2005.\n\nRingkasan editorial SIMANTRI; belum divalidasi ahli. Bukan hasil pemeriksaan lapangan atau kerja sama resmi Dinas Pertanian.","metadata":{"catalogue":"pm-disease-v1","disease":{"scientific_name":"Stemphylium vesicarium","aliases":["stemphylium","ngelumpruk","leumpeuh","hawar daun stemphylium"],"parts":["Daun"],"symptoms":["Amati bercak awal berwarna kuning muda atau cokelat muda pada daun.","Bercak yang meluas dapat menyatu. Bagian yang rusak dapat menggelap dan membusuk.","Pada tanaman yang sedang berbunga, tangkai bunga yang terserang dapat mengering dan terkulai."],"prevention":["Pilih bahan tanam yang sehat dan singkirkan sisa tanaman sakit dari lahan.","Pantau daun lebih sering ketika tajuk lama lembap atau banyak embun.","Pada pertanaman untuk benih biji, periksa daun dan tangkai bunga sejak awal pembungaan."],"first_steps":["Catat letak dan perkembangan bercak pada beberapa tanaman.","Jika tanaman berbunga, periksa tangkai bunga yang mengering atau terkulai.","Tunjukkan foto dan catatan perkembangan gejala kepada POPT atau penyuluh sebelum memilih tindakan pengendalian."],"confused_with":"Hawar Stemphylium dapat muncul bersama bercak ungu. Warna bercak yang menggelap saja belum cukup untuk membedakan keduanya.","sources":[{"title":"Benih Biji Bawang Merah di Indonesia · bagian 6.2.5 dan 6.4","publisher":"Rosliani dkk., IAARD Press, Kementerian Pertanian","year":"2022","url":"https://repository.pertanian.go.id/server/api/core/bitstreams/4a250672-f833-42cc-83d5-35327f1d5e3e/content"},{"title":"Pengenalan Hama dan Penyakit pada Tanaman Bawang Merah dan Pengendaliannya · bagian 2.2.5","publisher":"Udiarto, Setiawati & Suryaningsih, Balai Penelitian Tanaman Sayuran","year":"2005","url":"https://repository.pertanian.go.id/server/api/core/bitstreams/2cae6926-4681-4cfc-b1dc-2219b18c474d/content#page=29"}],"photo_reference":{"url":"https://repository.pertanian.go.id/server/api/core/bitstreams/4a250672-f833-42cc-83d5-35327f1d5e3e/content","label":"Gambar 31 · halaman tercetak 93 · gejala pada tangkai bunga","credit":"Sulastrini (2020), dikutip dalam Rosliani dkk. (2022). Izin penggunaan ulang belum dikonfirmasi."}}},"keywords":["Hawar daun Stemphylium","stemphylium","ngelumpruk","leumpeuh","hawar daun stemphylium","Stemphylium vesicarium"],"source_title":"Benih Biji Bawang Merah di Indonesia · bagian 6.2.5 dan 6.4","source_url":"https://repository.pertanian.go.id/server/api/core/bitstreams/4a250672-f833-42cc-83d5-35327f1d5e3e/content"}]'::jsonb) as item(doc_id text,title text,summary text,content text,keywords text[],source_title text,source_url text,metadata jsonb)
